function ValidateAssigned_WS() {

    //   gsftSubmit(null, g_form.getFormElement(), 'sysverb_insert_task');

    if (g_form.getValue('outcome') == '' && g_form.getValue('trade_task_type') == 'Maker') {
        g_form.setMandatory('outcome', true);
        g_form.clearMessages();
        g_form.addErrorMessage("Fill Outcome field before submitting the task");
        return false;
    }
    if (g_form.getValue('decision') == '' && g_form.getValue('trade_task_type') == 'Checker') {
        g_form.setMandatory('decision', true);
        g_form.clearMessages();
        g_form.addErrorMessage("Fill Decision field before submitting the task");
        return false;
    }


    if ( /*g_form.mandatoryCheck() &&*/ g_form.getValue('assigned_to') == '') {
        g_form.setMandatory('assigned_to', true);
        g_form.clearMessages();
        g_form.addErrorMessage("Fill Assigned to field before submitting the task");
        return false;
    }

    var assigneeUser = g_user.userID;
    if (g_form.getValue('assigned_to') != assigneeUser) {
        if (assigneeUser == g_form.getValue('trade_case_id.current_maker_assignee')) {
            g_form.setValue('assigned_to', '');
            g_form.setMandatory('assigned_to', true);
            g_form.clearMessages();
            g_form.addErrorMessage("Checker cannot be the same user who actioned the maker task");
            return false;
        } else
            g_form.setValue('assigned_to', assigneeUser);
    }

    if (g_form.getValue('outcome') == 'Amend Trade') {

        if (g_form.getValue('validate_amend_fields').toString() == "false") {
            g_form.addErrorMessage("Please Check the Verify fields to proceed validation of the amend inputs ");
            return false;
        }
    }



    //gsftSubmit(null, g_form.getFormElement(), 'sysverb_insert_task');
    //g_form.save();



    if (g_form.getValue('outcome') == 'Review and closed the task') {
        g_form.setValue('state', 3); //Closed complete
        var ga = new GlideAjax("x_hsb11_mss_c_proc.HSBCTradeTaskUtils");
        ga.addParam('source_record_sys_id', g_form.getValue('trade_case_id'));
        ga.addParam('cancelReason', 'Cancelling in-progress flows as outcome is Review and Closed the task');
        ga.addParam('sysparm_name', 'cancelFlowWS');

        ga.getXMLAnswer(function(response) {
            if (response == 'false') {
                alert("Error Occured when create the case!");
            }
        });

        g_form.setValue('work_notes', 'Cancelling in-progress flows as outcome is Review and Closed the task');
    }

    g_form.setValue('state', 3); //Closed complete.
    //Set state as 'Awaiting info' for Amend trade Outcome on Submit
    if (g_form.getValue('outcome') == 'Amend Trade') {
        g_form.setValue('state', 6);
        g_form.setValue('work_notes', "GHSS amendment is in progress. Awaiting response from RPA");
        g_form.setValue('outbound_created', true);
    }


    if (g_form.getValue('trade_task_type') == 'Checker' && g_form.getValue('decision') == 'Reject and create a new task') {
        g_form.setValue('sub_trade_task_type', 'Checker-Rejected');
    }
    console.log('assignment_group: ' + g_form.getValue('assignment_group'));

    g_form.save();
    //g_form.submit('sysverb_insert_task');

